import assert from 'node:assert/strict';
import { ingest } from './skills/prism/corpus/index.ts';
const faults=[['corpus_item','INSERT'],['corpus_revision','INSERT'],['corpus_embedding','INSERT'],['corpus_item','UPDATE'],['rights_policy','INSERT']];
for(const fault of [...faults,null]) {
 let acquired=0,released=0,poolQueries=0,active=false;const events=[];
 const client={async query(sql,args){assert.equal(active,true,'no query after client release');events.push(sql);if(fault&&sql.startsWith(`${fault[1]}${fault[1]==='INSERT'?' INTO':''} prism.${fault[0]}`))throw new Error(`injected-${fault.join('-')}`);return {rows:[]};},release(){assert.equal(active,true);assert.ok(['COMMIT','ROLLBACK'].includes(events.at(-1)),'transaction settles before release');active=false;released++;}};
 const pool={async connect(){acquired++;active=true;return client},async query(){poolQueries++;throw new Error('transaction escaped reserved client')}};
 const input={sourceKind:'internal-project',title:'reserved-client-boundary',summary:'atomic',tags:[],rights:'full'};
 const evidence={embedding:[1,0],model:'pool-test',modelVersion:'1',sourceDigest:`sha256:${'a'.repeat(64)}`};
 if(fault)await assert.rejects(ingest(pool,input,evidence),new RegExp(`injected-${fault.join('-')}`));else assert.ok((await ingest(pool,input,evidence)).id);
 assert.equal(acquired,1);assert.equal(released,1);assert.equal(poolQueries,0);assert.equal(events[0],'BEGIN');assert.equal(events.at(-1),fault?'ROLLBACK':'COMMIT');
 console.log(JSON.stringify({fault,acquired,released,poolQueries,terminal:events.at(-1),qualification:'instrumented production ingest boundary; NOT native PostgreSQL or pool interleaving acceptance'}));
}

